app.use((req, res, next) => {
  const start = process.hrtime.bigint();
  res.on('finish', () => {
    const seconds = Number(process.hrtime.bigint() - start) / 1e9;
    // BUG 1: counts 4xx (client errors) as service errors
    if (res.statusCode >= 400) errs.inc({ method: req.method, route: req.url });
    // BUG 2: req.url carries the query string
    reqs.inc({ method: req.method, route: req.url, status_code: res.statusCode });
    dur.observe({ method: req.method, route: req.url }, seconds);
  });
  next();
});
